{"cards": [{"node_code": "N_6267cf986c312ffe", "definition": "研究骨盆、盆腔脏器及会阴部骨骼、肌肉、神经、血管等结构的空间毗邻、层次关系及其临床意义的局部解剖学分支。", "boundary": "本节点聚焦于骨盆上口以下、腹股沟韧带以下的区域，包括骨盆腔、直肠膀胱/子宫陷凹、会阴浅深隙等。重点在于盆腔脏器与周围血管神经的立体关系，以及分娩、手术入路涉及的解剖结构。与四肢局解的区别在于解剖界限以骨盆上口/腹股沟韧带为界，不涉及肢体远端结构。", "includes": ["骨盆骨性结构、盆腔筋膜及盆腔脏器（膀胱、直肠、生殖器官）的毗邻关系", "会阴部肌层、筋膜间隙及神经血管分布", "盆腔手术入路及分娩机制涉及的局部解剖结构"], "excludes": ["上肢及下肢的局部解剖（归入上肢或下肢局部解剖）", "胸廓内及腹腔内器官结构（归入胸腹局解）"], "sibling_distinctions": [{"other_code": "N_54c5b2a584946761", "rule": "盆部与会阴局解关注骨盆、盆腔及会阴区域；上肢局解关注肩、臂、前臂及手，两者以躯干与肢体的连接处为界。"}, {"other_code": "N_7256d252a2779a3e", "rule": "盆部与会阴局解关注骨盆、盆腔及会阴区域；下肢局解关注髋、大腿、小腿及足，两者以腹股沟韧带/骨盆上口为界。"}], "cross_boundary_rule": "若内容涉及骨盆上口或腹股沟韧带附近的交界结构，以主要解剖结构所在区域为主挂载；若为跨区域的连续结构描述，可依据主要临床关注点归类。"}, {"node_code": "N_54c5b2a584946761", "definition": "研究上肢（肩、臂、前臂、手）区域内骨骼、肌肉、神经、血管及器官的空间毗邻、层次结构及其临床关系的局部解剖学分支。", "boundary": "本节点涵盖上肢各段（肩、臂、前臂、手）的解剖结构，重点在于多系统结构的立体整合，如臂丛神经与腋血管的关系、前臂骨筋膜室结构。与盆部局解的区别在于解剖界限以躯干与肢体的连接处（如肩关节、腋窝）为界，不涉及盆腔结构。", "includes": ["肩、臂、前臂、手的骨、肌、神经、血管毗邻关系", "上肢骨筋膜室、腱鞘及滑囊结构", "上肢手术入路及损伤涉及的局部解剖结构"], "excludes": ["盆部、会阴及下肢的局部解剖（归入盆部会阴或下肢局部解剖）", "单一系统（如仅骨骼或仅神经）的全身性分布描述（归入系统解剖）"], "sibling_distinctions": [{"other_code": "N_6267cf986c312ffe", "rule": "上肢局解关注肩、臂、前臂及手；盆部与会阴局解关注骨盆、盆腔及会阴区域，两者以躯干与肢体的连接处为界。"}, {"other_code": "N_7256d252a2779a3e", "rule": "上肢局解关注上肢各段结构；下肢局解关注髋、大腿、小腿及足，两者以躯干为界，分别位于身体两侧。"}], "cross_boundary_rule": "若内容涉及上肢与躯干的交界区域（如腋窝、肩关节），以主要解剖结构所在区域为主挂载；若为跨区域的连续结构描述，可依据主要临床关注点归类。"}, {"node_code": "N_7256d252a2779a3e", "definition": "研究下肢（髋、大腿、小腿、足）区域内骨骼、肌肉、神经、血管及器官的空间毗邻、层次结构及其临床关系的局部解剖学分支。", "boundary": "本节点涵盖下肢各段（髋、大腿、小腿、足）的解剖结构，重点在于多系统结构的立体整合，如股三角、腘窝、足底筋膜室等。与盆部局解的区别在于解剖界限以腹股沟韧带/骨盆上口为界，不涉及盆腔脏器结构。", "includes": ["髋、大腿、小腿、足的骨、肌、神经、血管毗邻关系", "下肢骨筋膜室、腱鞘及滑囊结构", "下肢手术入路及损伤涉及的局部解剖结构"], "excludes": ["盆部、会阴及上肢的局部解剖（归入盆部会阴或上肢局部解剖）", "单一系统（如仅骨骼或仅神经）的全身性分布描述（归入系统解剖）"], "sibling_distinctions": [{"other_code": "N_6267cf986c312ffe", "rule": "下肢局解关注髋、大腿、小腿及足；盆部与会阴局解关注骨盆、盆腔及会阴区域，两者以腹股沟韧带/骨盆上口为界。"}, {"other_code": "N_54c5b2a584946761", "rule": "下肢局解关注下肢各段结构；上肢局解关注肩、臂、前臂及手，两者以躯干为界，分别位于身体两侧。"}], "cross_boundary_rule": "若内容涉及下肢与盆部的交界区域（如腹股沟韧带、髋关节），以主要解剖结构所在区域为主挂载；若为跨区域的连续结构描述，可依据主要临床关注点归类。"}]}
